<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Teacher,Department};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class TeacherController extends Controller{public function index(){return view('admin.teachers.index',['items'=>Teacher::with('department')->orderBy('sort')->paginate(30)]);}public function create(){return $this->form(new Teacher);}public function store(Request $r){Teacher::create($this->data($r));return redirect()->route('admin.teachers.index')->with('ok','Преподаватель добавлен');}public function edit(Teacher $teacher){return $this->form($teacher);}public function update(Request $r,Teacher $teacher){$old=$teacher->photo;$d=$this->data($r,$teacher);$teacher->update($d);if(isset($d['photo'])&&$old&&$old!==$d['photo'])Storage::disk('public')->delete($old);return redirect()->route('admin.teachers.index')->with('ok','Сохранено');}public function destroy(Teacher $teacher){if($teacher->photo)Storage::disk('public')->delete($teacher->photo);$teacher->delete();return back();}private function form($item){return view('admin.teachers.form',['item'=>$item,'departments'=>Department::orderBy('sort')->get()]);}private function data(Request $r,?Teacher $item=null){$d=$r->validate(['name'=>'required|max:255','department_id'=>'nullable|exists:departments,id','position'=>'nullable|max:255','education'=>'nullable|max:1000','qualification'=>'nullable|max:1000','experience_years'=>'nullable|integer|min:0|max:100','awards'=>'nullable','bio'=>'nullable','photo'=>'nullable|image|max:10240','sort'=>'nullable|integer']);$base=Str::slug($r->input('slug')?:$d['name'])?:'teacher';$slug=$base;$i=2;while(Teacher::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('photo'))$d['photo']=$r->file('photo')->store('teachers','public');$d['is_active']=$r->boolean('is_active');return $d;}}